 s=s.replace(/\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{30,}|sk-[A-Za-z0-9_-]{20,})\b/g,()=>{redactions++;return '[CREDENCIAL OMITIDA]'})
 s=s.replaceAll('/workspace/worktree','/workspace/worktree').replaceAll(root,'/workspace/main').replaceAll('/home/usuario','/home/usuario')
 return typeof value==='string'?s:JSON.parse(s)
}
for(const file of files){
 const records=readFileSync(file,'utf8').split('\n').filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean)
 const meta=records.find(r=>r.type==='session_meta')?.payload
 if(!meta)continue
 const id=meta.id
 let messageCount=0,callCount=0
 for(const r of records){
  if(r.timestamp>cut||r.type!=='response_item')continue
  const p=r.payload
  if(p.type==='message'&&['user','assistant'].includes(p.role)&&p.channel!=='analysis'){
   const content=(p.content??[]).filter(c=>['input_text','output_text'].includes(c.type)).map(c=>scrub(c.text))
   if(content.length){messages.push({session:id,timestamp:r.timestamp,role:p.role,phase:p.phase??null,content});messageCount++}
  }else if(p.type==='agent_message'){
   messages.push({session:id,timestamp:r.timestamp,role:'agent_message',author:p.author,recipient:p.recipient,content:scrub(p.content)});messageCount++
  }else if(['function_call','custom_tool_call'].includes(p.type)){
   let input=p.type==='custom_tool_call'?p.input:p.arguments
   if(p.type==='function_call'){try{input=JSON.parse(input)}catch{}}
   input=scrub(input)
   const call={session:id,timestamp:r.timestamp,call_id:p.call_id,tool:p.name,format:p.type,input}
   calls.push(call);callCount++
   if(JSON.stringify(input).includes('SKILL.md'))skills.push({...call,evidence:'La llamada contiene una referencia a SKILL.md; el texto permite distinguir lectura de instrucciones y referencia en un encargo.'})
  }
 }
 sessions.push({id,source:scrub(meta.source??null),workspace:scrub(meta.cwd??''),messages:messageCount,calls:callCount})
}
messages.sort((a,b)=>a.timestamp.localeCompare(b.timestamp));calls.sort((a,b)=>a.timestamp.localeCompare(b.timestamp))
